package com.studybuddy.api.domain;
import jakarta.persistence.*;
import java.time.Instant;
@Entity @Table(name="reports")
public class Report { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="reporter_id",nullable=false) private User reporter; @Column(name="target_type",nullable=false,length=32) private String targetType; @Column(name="target_id",nullable=false) private Long targetId; @Column(nullable=false,length=1000) private String reason; @Enumerated(EnumType.STRING) @Column(nullable=false) private ReportStatus status=ReportStatus.OPEN; @Column(name="created_at",nullable=false) private Instant createdAt=Instant.now(); protected Report(){} public Report(User reporter,String type,Long target,String reason){this.reporter=reporter;targetType=type;targetId=target;this.reason=reason;} public Long getId(){return id;} public User getReporter(){return reporter;} public String getTargetType(){return targetType;} public Long getTargetId(){return targetId;} public String getReason(){return reason;} public ReportStatus getStatus(){return status;} public void resolve(ReportStatus status){this.status=status;} }
